"use client";

import { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polygon } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { io } from 'socket.io-client';

const socket = io('http://localhost:3001');

const crearIconoNodo = (estado: string) => L.divIcon({
  className: 'custom-leaflet-icon',
  html: `<div class="relative flex h-5 w-5 items-center justify-center">
           ${estado?.toLowerCase() === 'alerta' ? '<span class="absolute inline-flex h-full w-full animate-ping rounded-full bg-red-400 opacity-75"></span>' : ''}
           <span class="relative inline-flex h-3 w-3 rounded-full ${estado?.toLowerCase() === 'alerta' ? 'bg-red-500' : 'bg-agrogreen-500'} shadow-lg border border-white z-10"></span>
         </div>`,
  iconSize: [20, 20],
  iconAnchor: [10, 10],
});

const iconoGateway = L.divIcon({
  className: 'custom-leaflet-icon',
  html: `<div class="relative flex h-8 w-8 items-center justify-center">
           <span class="relative inline-flex h-4 w-4 rounded-full bg-blue-500 shadow-lg border-2 border-white z-10"></span>
         </div>`,
  iconSize: [32, 32],
  iconAnchor: [16, 16],
});

// AHORA ACEPTAMOS EL ID DEL CLIENTE COMO PROP (Por defecto intentará con el 1 o el que le pases)
export default function MapaTopografico({ clienteId = 1 }: { clienteId?: number }) {
  const centro: [number, number] = [-33.7347105121274, -70.76633205905223];
  
  const [datosMapa, setDatosMapa] = useState<any>(null);
  const [cargando, setCargando] = useState(true);
  const [errorApi, setErrorApi] = useState<string | null>(null); // Nuevo estado para manejar errores

  useEffect(() => {
    // Usamos el clienteId dinámico
    fetch(`http://localhost:3001/api/mapa/cliente/${clienteId}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.error) {
          setErrorApi(data.error);
        } else {
          setDatosMapa(data);
        }
        setCargando(false);
      })
      .catch((err) => {
        console.error('Error cargando el mapa:', err);
        setErrorApi('Error de conexión con el servidor');
        setCargando(false);
      });

    socket.on('alerta_nodo', (alerta) => {
      setDatosMapa((prevDatos: any) => {
        if (!prevDatos || !prevDatos.sectores) return prevDatos;
        
        const nuevosSectores = prevDatos.sectores.map((sector: any) => ({
          ...sector,
          nodos: sector.nodos.map((nodo: any) => 
            nodo.id === alerta.nodoId ? { ...nodo, estado: 'ALERTA' } : nodo
          )
        }));

        return { ...prevDatos, sectores: nuevosSectores };
      });
    });

    return () => {
      socket.off('alerta_nodo');
    };
  }, [clienteId]);

  if (cargando) {
    return <div className="flex h-full w-full items-center justify-center bg-gray-50 text-gray-500">Cargando infraestructura agrícola...</div>;
  }

  if (errorApi || !datosMapa) {
    return (
      <div className="flex h-full w-full flex-col items-center justify-center bg-red-50 text-red-500 p-4 text-center">
        <p className="font-bold text-lg">No se pudo cargar el mapa</p>
        <p>{errorApi}</p>
        <p className="text-sm mt-2 text-gray-500">Asegúrate de que el ID del cliente sea el correcto en la URL.</p>
      </div>
    );
  }

  // Agregamos el operador "?." (Optional Chaining) para que nunca más explote si falta un dato
  const todosLosNodos = datosMapa.sectores?.flatMap((sector: any) => sector.nodos) || [];

  return (
    <MapContainer center={centro} zoom={15} className="w-full h-full z-0">
      <TileLayer
        url="https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}"
        attribution='&copy; Esri'
      />
      
      {datosMapa.infraestructuras?.map((infra: any) => (
        <Polygon key={`infra-${infra.id}`} positions={infra.coordenadas} pathOptions={{ color: infra.color, fillColor: infra.color, fillOpacity: 0.4, weight: 2 }} />
      ))}

      {datosMapa.sectores?.map((sector: any) => (
        <Polygon key={`sector-${sector.id}`} positions={sector.coordenadas} pathOptions={{ color: sector.color, fillColor: sector.color, fillOpacity: 0.2, weight: 2 }} />
      ))}

      {datosMapa.gateways?.map((gw: any) => (
        <Marker key={gw.id} position={[gw.latitud, gw.longitud]} icon={iconoGateway}>
          <Popup className="rounded-lg">
            <span className="font-bold text-blue-600">{gw.nombre}</span><br/>
            Estado: {gw.estado}
          </Popup>
        </Marker>
      ))}

      {todosLosNodos.map((nodo: any) => (
        <Marker key={nodo.id} position={[nodo.latitud, nodo.longitud]} icon={crearIconoNodo(nodo.estado)}>
          <Popup className="rounded-lg">
            <span className={`font-bold ${nodo.estado === 'ALERTA' ? 'text-red-600' : 'text-gray-900'}`}>
              {nodo.id} {nodo.estado === 'ALERTA' && '(Alerta)'}
            </span><br/>
            Gateway Enlace: {nodo.gatewayId}<br/>
            {nodo.estado === 'ALERTA' && <span className="text-xs text-red-500">Cavitación Detectada</span>}
          </Popup>
        </Marker>
      ))}
    </MapContainer>
  );
}